package com.madhukar.upisplitter.config;
import org.springframework.beans.factory.annotation.Value;import org.springframework.context.annotation.*;import software.amazon.awssdk.auth.credentials.*;import software.amazon.awssdk.regions.Region;import software.amazon.awssdk.services.s3.S3Client;
@Configuration public class AwsConfig { @Bean public S3Client s3Client(@Value("${aws.region}") String region,@Value("${aws.access-key-id:}") String key,@Value("${aws.secret-access-key:}") String secret){if(key.isBlank()||secret.isBlank())return S3Client.builder().region(Region.of(region)).credentialsProvider(DefaultCredentialsProvider.create()).build();return S3Client.builder().region(Region.of(region)).credentialsProvider(StaticCredentialsProvider.create(AwsBasicCredentials.create(key,secret))).build();}}
